# ==== .DraggableIcon (linha 1266)
__module__ = __name__
__qualname__ = "DraggableIcon"

def __init__(self, pixmap, text, icon_id, power_direction=1, parent=None):
    super().__init__(pixmap, parent)
    self._signal_emitter = IconSignalEmitter()
    self.setFlag(QGraphicsPixmapItem.ItemIsMovable)
    self.setFlag(QGraphicsPixmapItem.ItemIsSelectable)
    self.setFlag(QGraphicsPixmapItem.ItemSendsGeometryChanges)
    self.setAcceptHoverEvents(True)
    self.orientation = Qt.Vertical
    self.base_pixmap = pixmap
    self.text = text
    self.icon_id = icon_id
    self.power_direction = power_direction
    self.font_size = 26
    self.update_pixmap()


@property
def positionChanged(self):
    return self._signal_emitter.positionChanged


@property
def powerDirectionChanged(self):
    return self._signal_emitter.powerDirectionChanged


def update_pixmap(self):
    """更新图标和文字方向，边缘10像素为红色"""
    if self.orientation == Qt.Vertical:
        new_pix = QPixmap(self.base_pixmap.size())
        new_pix.fill(Qt.white)
        painter = QPainter(new_pix)
        border_pen = QPen(Qt.red)
        border_pen.setWidth(10)
        painter.setPen(border_pen)
        painter.drawRect(0, 0, new_pix.width(), new_pix.height())
        content_rect = QRectF(10, 10, new_pix.width() - 20, new_pix.height() - 20)
        painter.drawPixmap(content_rect, self.base_pixmap, QRectF(self.base_pixmap.rect()))
        font = painter.font()
        font.setPixelSize(self.font_size)
        painter.setFont(font)
        painter.setPen(Qt.black)
        text_rect = QRectF(10, 10, new_pix.width() - 20, new_pix.height() - 20)
        painter.drawText(text_rect, Qt.AlignCenter, self.text)
        painter.end()
    else:
        new_pix = QPixmap(self.base_pixmap.height(), self.base_pixmap.width())
        new_pix.fill(Qt.white)
        painter = QPainter(new_pix)
        border_pen = QPen(Qt.red)
        border_pen.setWidth(10)
        painter.setPen(border_pen)
        painter.drawRect(0, 0, new_pix.width(), new_pix.height())
        transform = QTransform()
        transform.translate(new_pix.width() / 2, new_pix.height() / 2)
        transform.rotate(90)
        transform.translate(-self.base_pixmap.width() / 2, -self.base_pixmap.height() / 2)
        painter.setTransform(transform)
        content_rect = QRectF(10, 10, self.base_pixmap.width() - 20, self.base_pixmap.height() - 20)
        painter.drawPixmap(content_rect, self.base_pixmap, QRectF(self.base_pixmap.rect()))
        painter.resetTransform()
        font = painter.font()
        font.setPixelSize(self.font_size)
        painter.setFont(font)
        painter.setPen(Qt.black)
        text_rect = QRectF(10, 10, new_pix.width() - 20, new_pix.height() - 20)
        painter.drawText(text_rect, Qt.AlignCenter, self.text)
        painter.end()
    self.setPixmap(new_pix)


def update_pixmap_new(self):
    """更新图标和文字方向，根据power_direction显示不同位置的红色边框"""
    if self.orientation == Qt.Vertical:
        new_pix = QPixmap(self.base_pixmap.size())
        new_pix.fill(Qt.white)
        painter = QPainter(new_pix)
        background_pen = QPen(Qt.white)
        background_pen.setWidth(10)
        painter.setPen(background_pen)
        painter.drawRect(0, 0, new_pix.width(), new_pix.height())
        border_pen = QPen(Qt.red)
        border_pen.setWidth(10)
        painter.setPen(border_pen)
        if self.power_direction == 1:
            painter.drawLine(0, 0, new_pix.width(), 0)
        else:
            painter.drawLine(0, new_pix.height() - 1, new_pix.width(), new_pix.height() - 1)
        content_rect = QRectF(10, 10, new_pix.width() - 20, new_pix.height() - 20)
        painter.drawPixmap(content_rect, self.base_pixmap, QRectF(self.base_pixmap.rect()))
        font = painter.font()
        font.setPixelSize(self.font_size)
        painter.setFont(font)
        painter.setPen(Qt.black)
        text_rect = QRectF(10, 10, new_pix.width() - 20, new_pix.height() - 20)
        painter.drawText(text_rect, Qt.AlignCenter, self.text)
        painter.end()
    else:
        new_pix = QPixmap(self.base_pixmap.height(), self.base_pixmap.width())
        new_pix.fill(Qt.white)
        painter = QPainter(new_pix)
        background_pen = QPen(Qt.white)
        background_pen.setWidth(10)
        painter.setPen(background_pen)
        painter.drawRect(0, 0, new_pix.width(), new_pix.height())
        border_pen = QPen(Qt.red)
        border_pen.setWidth(10)
        painter.setPen(border_pen)
        if self.power_direction == 1:
            painter.drawLine(0, 0, 0, new_pix.height())
        else:
            painter.drawLine(new_pix.width() - 1, 0, new_pix.width() - 1, new_pix.height())
        transform = QTransform()
        transform.translate(new_pix.width() / 2, new_pix.height() / 2)
        transform.rotate(90)
        transform.translate(-self.base_pixmap.width() / 2, -self.base_pixmap.height() / 2)
        painter.setTransform(transform)
        content_rect = QRectF(10, 10, self.base_pixmap.width() - 20, self.base_pixmap.height() - 20)
        painter.drawPixmap(content_rect, self.base_pixmap, QRectF(self.base_pixmap.rect()))
        painter.resetTransform()
        font = painter.font()
        font.setPixelSize(self.font_size)
        painter.setFont(font)
        painter.setPen(Qt.black)
        text_rect = QRectF(10, 10, new_pix.width() - 20, new_pix.height() - 20)
        painter.drawText(text_rect, Qt.AlignCenter, self.text)
        painter.end()
    self.setPixmap(new_pix)


def set_orientation(self, orientation):
    if orientation != self.orientation:
        self.orientation = orientation
        self.update_pixmap()
        self.setPos(self.pos())
        self._signal_emitter.positionChanged.emit()


def set_power_direction(self, direction):
    if direction != self.power_direction:
        self.power_direction = direction
        self._signal_emitter.powerDirectionChanged.emit()
        self.update_pixmap()


def mousePressEvent(self, event):
    if event.button() == Qt.LeftButton:
        self.setCursor(Qt.ClosedHandCursor)
    super().mousePressEvent(event)


def mouseReleaseEvent(self, event):
    self.setCursor(Qt.OpenHandCursor)
    super().mouseReleaseEvent(event)
    self._signal_emitter.positionChanged.emit()


def hoverEnterEvent(self, event):
    self.setCursor(Qt.OpenHandCursor)
    super().hoverEnterEvent(event)


def hoverLeaveEvent(self, event):
    self.setCursor(Qt.ArrowCursor)
    super().hoverLeaveEvent(event)


def itemChange(self, change, value):
    if change == QGraphicsPixmapItem.ItemPositionChange:
        scene = self.scene()
        if scene is None:
            return value
        scene_rect = scene.sceneRect()
        new_pos = value
        icon_rect = self.boundingRect()
