__module__ = __name__
__qualname__ = "EffectSelector"
__doc__ = "独立的灯效选择组件"
effectChanged = Signal(str)

def __init__(self, effect_manager, parent=None):
    super().__init__("灯效选择", parent)
    self.setStyleSheet("\n            QGroupBox {\n                color: transparent;\n                border: 1px solid white;\n                border-radius: 3px;\n                margin-top: 0.5em;\n                background-color: transparent;\n            }\n            QGroupBox::title {\n                color: transparent;\n                subcontrol-origin: margin;\n                left: 10px;\n                padding: 0 3px;\n            }\n            QScrollArea {\n                border: none;\n            }\n            QScrollBar:vertical {\n                width: 10px;\n                background: transparent;\n            }\n            QScrollBar::handle:vertical {\n                background: transparent;\n                min-height: 16px;\n                border-radius: 4px;\n            }\n            QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {\n                height: 0px;\n            }\n        ")
    self.effect_manager = effect_manager
    self.init_ui()


def init_ui(self):
    main_layout = QVBoxLayout()
    main_layout.setContentsMargins(0, 0, 0, 0)
    self.setLayout(main_layout)
    scroll_area = QScrollArea()
    scroll_area.setWidgetResizable(True)
    scroll_area.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
    scroll_area.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
    main_layout.addWidget(scroll_area)
    container = QWidget()
    self.grid_layout = QGridLayout(container)
    self.grid_layout.setContentsMargins(5, 5, 5, 5)
    scroll_area.setWidget(container)
    if port.PID_COMPAY == 1:
        self.buttons_name_en = ["rainbow", "wave", "block", "four_directions", "corner_fill",
         "music_visualizer", "diagonal_visualizer", "music_center_side"]
        self.buttons_name_zh = [
         "彩虹流动",
         "波浪",
         "积木",
         "四向平铺",
         "四角填充",
         "音乐1",
         "音乐2",
         "音乐3"]
    else:
        self.buttons_name_en = [
         "rainbow", "wave", "block", "four_directions", "corner_fill",
         "random_circle", "fourth_dimension", "bubble", "dna_helix", "radar",
         "impact", "gradient_push", "music_visualizer", "diagonal_visualizer",
         "music_center_side"]
        self.buttons_name_zh = [
         "彩虹流动",
         "波浪",
         "积木",
         "四向平铺",
         "四角填充",
         "随机圆环",
         "四次元",
         "气泡",
         "DNA 螺旋",
         "雷达扫描",
         "撞击效果",
         "渐变推动",
         "音乐1",
         "音乐2",
         "音乐3"]
    self.buttons = {}
    self.create_buttons()
    self.update_button_states()


def create_buttons(self):
    for i in reversed(range(self.grid_layout.count())):
        widget = self.grid_layout.itemAt(i).widget()
        if widget:
            widget.deleteLater()
        self.buttons.clear()

    for idx, effect_name in enumerate(self.buttons_name_en):
        name_zh = self.effect_manager.effects[effect_name]["name"]
        btn = QPushButton(name_zh)
        btn.setCheckable(True)
        btn.setCursor(Qt.PointingHandCursor)
        btn.setStyleSheet("\n                QPushButton {\n                    background-color: #444;\n                    color: white;\n                    border: 1px solid #666;\n                    border-radius: 3px;\n                    padding: 5px;\n                    margin: 2px;\n                }\n                QPushButton:hover {\n                    background-color: #555;\n                }\n                QPushButton:checked {\n                    background-color: #0078d7;\n                    border-color: #005fa3;\n                }\n                QPushButton:pressed {\n                    background-color: #005fa3;\n                }\n            ")
        btn.setMinimumHeight(30)
        btn.clicked.connect(lambda checked=False, e=effect_name: self.on_effect_changed(e))
        line = 6
        row = idx // line
        col = idx % line
        self.grid_layout.addWidget(btn, row, col)
        self.buttons[effect_name] = btn


def on_effect_changed(self, effect_name):
    self.effect_manager.current_effect = effect_name
    self.effect_manager.save_config()
    self.update_button_states()
    self.effectChanged.emit(effect_name)


def update_button_states(self):
    current = self.effect_manager.current_effect
    for name, btn in self.buttons.items():
        btn.setChecked(name == current)


def wheelEvent(self, event):
    scroll_area = self.findChild(QScrollArea)
    if scroll_area:
        scroll_bar = scroll_area.verticalScrollBar()
        delta = event.angleDelta().y()
        scroll_bar.setValue(scroll_bar.value() - delta // 3)
    event.accept()
